        { q: `${chTitle}: পরমাণুর নিউক্লিয়াস কে আবিষ্কার করেন?`, o: opts("রাদারফোর্ড", "নিলস বোর", "জন ডাল্টন", "জে জে থমসন"), a: "রাদারফোর্ড", d: "১৯১১ সালে আলফা কণা বিচ্ছুরণ পরীক্ষার (Alpha scattering experiment) মাধ্যমে বিজ্ঞানী আর্নেস্ট রাদারফোর্ড পরমাণুর কেন্দ্রে নিউক্লিয়াসের উপস্থিতি প্রমাণ করেন।", f: "রাদারফোর্ড আলফা পরীক্ষা" },
        { q: `${chTitle}: বোর মডেল অনুযায়ী পরমাণুর ৩য় প্রধান শক্তিস্তরে (M shell) সর্বোচ্চ কয়টি ইলেকট্রন থাকতে পারে?`, o: opts("১৮টি", "৮টি", "৩২টি", "২টি"), a: "১৮টি", d: "প্রধান শক্তিস্তরে সর্বোচ্চ ইলেকট্রন ধারণক্ষমতা ২n²। ৩য় স্তরের ক্ষেত্রে n = ৩। সুতরাং সর্বোচ্চ ইলেকট্রন = ২ × ৩² = ১৮টি।", f: "Max Electrons = 2n²" },
        { q: `${chTitle}: ক্যান্সার কোষ ধ্বংসে ও থেরাপিতে কোন তেজস্ক্রিয় আইসোটোপটি ব্যবহৃত হয়?`, o: opts("Co-60", "I-131", "C-14", "P-32"), a: "Co-60", d: "কোবাল্ট-৬০ (Co-60) আইসোটোপ থেকে নির্গত অত্যন্ত শক্তিশালী গামা রশ্মি ক্যান্সার কোষ ধ্বংস করার জন্য রেডিওথেরাপিতে ব্যবহৃত হয়।", f: "Radiation Therapy" },
        { q: `${chTitle}: পরমাণুর ইলেকট্রন বিন্যাসের ক্ষেত্রে ১৯তম ইলেকট্রনটি ৩d উপস্তরে না গিয়ে ৪s এ যায় কেন?`, o: opts("৪s এর শক্তি ৩d অপেক্ষা কম", "৪s এর আকার বড়", "৩d এর ধারণক্ষমতা বেশি", "৪s একটি প্রধান স্তর"), a: "৪s এর শক্তি ৩d অপেক্ষা কম", d: "আউফবাউ নীতি অনুযায়ী ইলেকট্রন প্রথমে নিম্ন শক্তির উপস্তরে প্রবেশ করে। ৩d এর শক্তি (n+l = 3+2 = 5) এবং ৪s এর শক্তি (n+l = 4+0 = 4)। ৪s এর শক্তি কম থাকায় ইলেকট্রন ৪s এ যায়।", f: "n + l নিয়ম" }
