        { q: `${chTitle}: ax + by = c এবং dx + ey = f সমীকরণ জোটে a/d != b/e হলে সমাধান সংখ্যা কতটি?`, o: opts("একটি মাত্র সমাধান", "অসংখ্য সমাধান", "কোনো সমাধান নেই", "দুটি সমাধান"), a: "একটি মাত্র সমাধান", d: "যদি সমীকরণ জোটের চলকদ্বয়ের সহগের অনুপাত অসমান হয় (a/d != b/e), তবে সমীকরণ জোটটি সমঞ্জস ও স্বাধীন এবং এর একটি মাত্র (অনন্য) সমাধান থাকে।", f: "a₁/a₂ != b₁/b₂" },
        { q: `${chTitle}: আরআড়ি গুণন বা বজ্রগুণন (Cross-multiplication) সূত্রের মৌলিক গাণিতিক রূপ নিচের কোনটি?`, o: opts("x / (bf - ce)", "বোর্ড মান অনুযায়ী বজ্রগুণন সূত্র প্রযোজ্য", "x/a = y/b", "কোনোটিই নয়"), a: "বোর্ড মান অনুযায়ী বজ্রগুণন সূত্র প্রযোজ্য", d: "বজ্রগুণন পদ্ধতিতে সমীকরণ জোটের চলকদ্বয়ের মান খুব সহজে নির্ণয় করা যায়।", f: "Cross multiplication" },
        { q: `${chTitle}: x + 2y = 8 এবং 2x + 4y = 16 সমীকরণ জোটটির প্রকৃতি কেমন?`, o: opts("সমঞ্জস ও নির্ভরশীল (অসংখ্য সমাধান)", "অসমঞ্জস (সমাধান নেই)", "স্বাধীন (একটি সমাধান)", "অবাস্তব"), a: "সমঞ্জস ও নির্ভরশীল (অসংখ্য সমাধান)", d: "সহগসমূহের অনুপাত: ১/২ = ২/৪ = ৮/১৬। সব অনুপাত সমান হওয়ায় সমীকরণদ্বয় মূলত একই সরলরেখা নির্দেশ করে। তাই এর অসংখ্য সমাধান রয়েছে।", f: "a₁/a₂ = b₁/b₂ = c₁/c₂" },
        { q: `${chTitle}: দুই চলক বিশিষ্ট সরল সহসমীকরণ বলতে কী বোঝায়?`, o: opts("চলকদ্বয়ের ঘাত ১ এবং তারা একসাথে সত্য হয়", "চলকদ্বয়ের ঘাত ২", "একটি মাত্র সমীকরণ", "অবাস্তব রাশি"), a: "চলকদ্বয়ের ঘাত ১ এবং তারা একসাথে সত্য হয়", d: "যেখানে দুটি চলকের ঘাত ১ থাকে এবং সমীকরণ দুটি চলকের একই মানের জন্য যুগপৎ সত্য হয়, তাকে সরল সহসমীকরণ বলে।", f: "ax + by = c" }
