        { q: `${chTitle}: বর্গের ঘূর্ণন প্রতিসমতার মাত্রা (Order of Rotational Symmetry) কত?`, o: opts("৪", "২", "১", "৩"), a: "৪", d: "একটি বর্গকে ৩৬০° কোণে ঘোরালে এটি তার আদি অবস্থানের সাথে হুবহু ৪ বার মিলে যায় (প্রতি ৯০° ঘূর্ণনে একবার)। তাই বর্গের ঘূর্ণন প্রতিসমতার মাত্রা ৪।", f: "Order = 4" },
        { q: `${chTitle}: একটি সমবাহু ত্রিভুজের ঘূর্ণন প্রতিসমতার কোণ কত ডিগ্রি?`, o: opts("১২০°", "৬০°", "১৮০°", "৯০°"), a: "১২০°", d: "সমবাহু ত্রিভুজের প্রতিসমতার মাত্রা ৩। ঘূর্ণন কোণ = ৩৬০° / মাত্রা = ৩৬০° / ৩ = ১২০°।", f: "Angle = 360° / n" },
        { q: `${chTitle}: একটি বৃত্তের ঘূর্ণন প্রতিসমতার মাত্রা কত?`, o: opts("অসীম", "১", "৩৬০", "০"), a: "অসীম", d: "বৃত্তকে কেন্দ্রের চারদিকে যেকোনো কোণে ঘোরালে এটি একই দেখায়। তাই এর ঘূর্ণন প্রতিসমতার মাত্রা অসীম।", f: "অসীম মাত্রা" },
        { q: `${chTitle}: সমদ্বিবাহু ত্রিভুজের প্রতিসাম্য রেখা (Line of Symmetry) কয়টি?`, o: opts("১টি", "৩টি", "২টি", "কোনোটিই নয়"), a: "১টি", d: "সমদ্বিবাহু ত্রিভুজের অসমান বাহুর বিপরীত শীর্ষ থেকে অঙ্কিত লম্ব ত্রিভুজটিকে সমান দুই ভাগে ভাগ করে। তাই এর প্রতিসাম্য রেখা কেবল ১টি।", f: "প্রতিসাম্য অক্ষ = 1" }
