        { q: `${chTitle}: পিথাগোরাসের উপপাদ্যটি কোন ধরনের ত্রিভুজের ক্ষেত্রে প্রযোজ্য?`, o: opts("সমকোণী ত্রিভুজ", "সমবাহু ত্রিভুজ", "সূক্ষ্মকোণী ত্রিভুজ", "স্থূলকোণী ত্রিভুজ"), a: "সমকোণী ত্রিভুজ", d: "সমকোণী ত্রিভুজের অতিভুজের ওপর অঙ্কিত বর্গক্ষেত্র অপর দুই বাহুর ওপর অঙ্কিত বর্গক্ষেত্রদ্বয়ের সমষ্টির সমান। এটি পিথাগোরাসের উপপাদ্য।", f: "c² = a² + b²" },
        { q: `${chTitle}: একটি সমকোণী ত্রিভুজের অতিভুজ ৫ সেমি এবং লম্ব ৩ সেমি হলে এর ক্ষেত্রফল কত বর্গ সেমি?`, o: opts("৬", "১২", "১৫", "৭.৫"), a: "৬", d: "ভূমি = √(৫² - ৩²) = √১৬ = ৪ সেমি। ক্ষেত্রফল = ০.৫ × ভূমি × লম্ব = ০.৫ × ৪ × ৩ = ৬ বর্গ সেমি।", f: "Area = 0.5 * b * h" },
        { q: `${chTitle}: অ্যাপোলোনিয়াসের উপপাদ্যটি ত্রিভুজের কোন বিষয়ের সম্পর্ক নির্দেশ করে?`, o: opts("বাহু ও মধ্যমার সম্পর্ক", "বাহু ও কোণের সম্পর্ক", "কোণ ও উচ্চতার সম্পর্ক", "বৃত্ত ও জ্যা"), a: "বাহু ও মধ্যমার সম্পর্ক", d: "অ্যাপোলোনিয়াসের উপপাদ্যের সাহায্যে ত্রিভুজের যেকোনো দুই বাহুর দৈর্ঘ্য এবং মধ্যমার দৈর্ঘ্যের সম্পর্ক গাণিতিকভাবে নির্ণয় করা যায়।", f: "AB² + AC² = 2(AD² + BD²)" },
        { q: `${chTitle}: সমকোণী ত্রিভুজের বাহুত্রয়ের অনুপাত নিচের কোনটি হতে পারে?`, o: opts("৩ : ৪ : ৫", "২ : ৩ : ৪", "১ : ২ : ৩", "৫ : ১০ : ১২"), a: "৩ : ৪ : ৫", d: "৩, ৪ এবং ৫ পিথাগোরাসের ত্রয়ী গঠন করে। কারণ ৩² + ৪² = ৯ + ১৬ = ২৫ = ৫²।", f: "3² + 4² = 5²" }
